/**
 * Regenerates src/tls/suite-registry.generated.ts from the IANA TLS cipher
 * suite registry (tls-parameters-4.csv).
 *
 * The generated file is committed, so the tool has no network dependency at
 * runtime. Run `node scripts/gen-suite-registry.ts <csv>` to refresh it.
 */
import { readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';

const here = dirname(fileURLToPath(import.meta.url));
const out = resolve(here, '..', 'src', 'tls', 'suite-registry.generated.ts');
const csvPath = process.argv[2];
if (!csvPath) {
  console.error('usage: node scripts/gen-suite-registry.ts <tls-parameters-4.csv>');
  process.exit(2);
}

type Row = { id: number; name: string; recommended: string; dtlsOk: string; ref: string };

/** Minimal RFC 4180 splitter: fields may be quoted and contain commas. */
function splitCsv(line: string): string[] {
  const fields: string[] = [];
  let cur = '';
  let quoted = false;
  for (let i = 0; i < line.length; i++) {
    const ch = line[i];
    if (quoted) {
      if (ch === '"' && line[i + 1] === '"') {
        cur += '"';
        i++;
      } else if (ch === '"') {
        quoted = false;
      } else {
        cur += ch;
      }
    } else if (ch === '"') {
      quoted = true;
    } else if (ch === ',') {
      fields.push(cur);
      cur = '';
    } else {
      cur += ch;
    }
  }
  fields.push(cur);
  return fields;
}

const lines = readFileSync(csvPath, 'utf8').split(/\r?\n/);
const rows: Row[] = [];
for (const line of lines.slice(1)) {
  if (!line.trim()) continue;
  // Columns: Value, Description, DTLS-OK, Recommended, Reference, Comment
  const f = splitCsv(line);
  if (f.length < 5 || f[0] === undefined || f[1] === undefined) continue;
  const vm = f[0].trim().match(/^(?:0x)?([0-9A-Fa-f]{2})\s*,\s*(?:0x)?([0-9A-Fa-f]{2})$/);
  if (!vm || vm[1] === undefined || vm[2] === undefined) continue;
  const id = parseInt(vm[1], 16) * 256 + parseInt(vm[2], 16);
  rows.push({
    id,
    name: f[1].trim(),
    // IANA uses Y (must), N (should not), D (DTLS-only), and blanks.
    recommended: (f[3]?.trim() ?? '') as Row['recommended'],
    dtlsOk: f[2]?.trim() ?? '',
    ref: f[4]?.trim() ?? '',
  });
}

// Group names by IANA "recommended" column: Y = MUST, D = DTLS-only (deprecated
// for TLS), N = not recommended, '' = unspecified.
const fmt = (r: Row) =>
  `  { id: 0x${r.id.toString(16).padStart(4, '0')}, name: ${JSON.stringify(r.name)}, ` +
  `recommended: ${JSON.stringify(r.recommended)}, ref: ${JSON.stringify(r.ref.replace(/; /g, ', '))} },`;

const body = rows.map(fmt).join('\n');
const file = `/**
 * Generated by scripts/gen-suite-registry.ts from
 * https://www.iana.org/assignments/tls-parameters/tls-parameters-4.csv
 *
 * DO NOT EDIT BY HAND. ${rows.length} entries.
 */

export interface CipherSuiteMeta {
  /** 16-bit cipher suite id. */
  readonly id: number;
  /** IANA name, e.g. TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256. */
  readonly name: string;
  /** IANA "Recommended" column: Y (must), D (DTLS-only/deprecated for TLS), N (no), '' (unspecified). */
  readonly recommended: 'Y' | 'D' | 'N' | '';
  /** IANA references. */
  readonly ref: string;
}

export const IANA_SUITES: readonly CipherSuiteMeta[] = [
${body}
];
`;
writeFileSync(out, file);
console.log(`wrote ${out} (${rows.length} suites)`);
